class Solution {
public:
    int numberOfPoints(vector<vector<int>>& nums) {
        bool seen[101] = {};
        for (auto& iv : nums)
            for (int x = iv[0]; x <= iv[1]; x++) seen[x] = true;
        int c = 0;
        for (bool b : seen) c += b;
        return c;
    }
};

