class Solution {
    public int numberOfPoints(List<List<Integer>> nums) {
        boolean[] seen = new boolean[101];
        for (List<Integer> iv : nums)
            for (int x = iv.get(0); x <= iv.get(1); x++) seen[x] = true;
        int c = 0;
        for (boolean b : seen) if (b) c++;
        return c;
    }
}

