class Solution:
    def numberOfPoints(self, nums: List[List[int]]) -> int:
        diff = [0] * 103
        for s, e in nums:
            diff[s] += 1
            diff[e + 1] -= 1
        ans = cur = 0
        for x in range(1, 102):
            cur += diff[x]
            if cur > 0:
                ans += 1
        return ans

