class Solution {
public:
    int numberOfPoints(vector<vector<int>>& nums) {
        vector<int> diff(103, 0);
        for (auto& iv : nums) { diff[iv[0]]++; diff[iv[1] + 1]--; }
        int ans = 0, cur = 0;
        for (int x = 1; x <= 101; x++) {
            cur += diff[x];
            if (cur > 0) ans++;
        }
        return ans;
    }
};

